"""Try to find a DOI from a given list of URLs.

Returns first matching DOI URL, or None.
"""
def extract_doi_links(urls: list[str]) -> str | None {
    doi_urls = [url for url in urls if "/doi/" in url];
    if not doi_urls {
        return None;
    }
    return doi_urls[0];
}

